<?php
/** Plain-text previews replace poster uploads; legacy media keeps its message ID. */
require __DIR__ . '/article-link-text.php';
add_filter( 'pre_http_request', 'treda_test_http', 10, 3 );
$settings = Treda_Settings::get(); $settings['article_link_text'] = ''; update_option( 'treda_settings', $settings );
$upload = wp_upload_bits( 'qa-preview-poster.png', null, file_get_contents( ABSPATH . 'wp-admin/images/wordpress-logo.png' ) );
treda_test_expect( ! $upload['error'], 'Disposable featured-image fixture is available' );
$attachment = wp_insert_attachment( array( 'post_title' => 'QA poster', 'post_mime_type' => 'image/png', 'post_status' => 'inherit' ), $upload['file'] );
$post = wp_insert_post( array( 'post_title' => 'Plain & preview QA', 'post_excerpt' => '<p>First <strong>paragraph</strong>.</p><p>Second paragraph.<br>New line.</p>', 'post_content' => '<img class="wp-image-' . $attachment . '" src="' . esc_url( $upload['url'] ) . '">', 'post_status' => 'publish', 'meta_input' => array( '_thumbnail_id' => $attachment ) ) );
$before = count( treda_test_methods( 'sendMessage' ) );
$before_photos = count( treda_test_methods( 'sendPhoto' ) );
treda_test_run();
$sent = treda_test_methods( 'sendMessage' ); $last = end( $sent );
$binding = get_post_meta( $post, '_treda_publication', true );
treda_test_expect( count( $sent ) === $before + 1 && count( treda_test_methods( 'sendPhoto' ) ) === $before_photos && $binding['media_type'] === 'text', 'A post with a featured image is sent as text and never uploaded as a separate poster' );
treda_test_expect( ! $last['files'] && ! isset( $last['params']['parse_mode'] ) && strpos( $last['params']['text'], "Plain & preview QA\n\nFirst paragraph.\n\nSecond paragraph.\n\nNew line." ) === 0, 'Plain text retains paragraphs and raw ampersands without rich formatting or files' );
treda_test_expect( $last['params']['link_preview_options'] === array( 'is_disabled' => false, 'url' => get_permalink( $post ), 'prefer_large_media' => true, 'show_above_text' => false ) && substr( $last['params']['text'], -strlen( get_permalink( $post ) ) ) === get_permalink( $post ), 'The visible article URL is the explicit large preview target below the text' );
$calls = count( $treda_test_calls ); Treda_Queue::post( $post ); treda_test_run();
treda_test_expect( count( $treda_test_calls ) === $calls, 'Repeating an unchanged preview job does not send or edit again' );
wp_update_post( array( 'ID' => $post, 'post_excerpt' => 'Changed preview. https://other.example/page' ) ); treda_test_run();
$edits = treda_test_methods( 'editMessageText' ); $last = end( $edits );
treda_test_expect( (int) $last['params']['message_id'] === (int) $binding['message_id'] && $last['params']['link_preview_options']['url'] === get_permalink( $post ) && ! isset( $last['params']['parse_mode'] ), 'An edited post updates the same text message and previews the article even when the excerpt contains another URL' );
update_post_meta( $post, '_thumbnail_id', 999999999 );
wp_update_post( array( 'ID' => $post, 'post_content' => '<img src="http://127.0.0.1/private.png">' ) ); treda_test_run();
treda_test_expect( count( $treda_test_calls ) === $calls + 1 && treda_test_job( 'post:' . $post )->status === 'done', 'Poster-only changes cause no request and inaccessible images cannot block text delivery' );
$broken = wp_insert_post( array( 'post_title' => 'Missing local poster QA', 'post_content' => '<img src="' . esc_url( content_url( 'uploads/missing-image.png' ) ) . '">', 'post_status' => 'publish', 'meta_input' => array( '_thumbnail_id' => 999999999 ) ) ); treda_test_run();
treda_test_expect( treda_test_job( 'post:' . $broken )->status === 'done' && get_post_meta( $broken, '_treda_publication', true )['media_type'] === 'text', 'A new post with a missing image still sends a text preview' );
$legacy = wp_insert_post( array( 'post_title' => 'Legacy photo & caption QA', 'post_excerpt' => 'Changed caption', 'post_status' => 'draft' ) );
$connection = Treda_Settings::connection();
update_post_meta( $legacy, '_treda_publication', array( 'bot_id' => $connection['bot_id'], 'chat_id' => $connection['chat_id'], 'message_id' => 67890, 'media_type' => 'photo', 'photo_hash' => 'legacy-file', 'hash' => 'legacy-html' ) );
wp_update_post( array( 'ID' => $legacy, 'post_status' => 'publish', 'meta_input' => array( '_thumbnail_id' => 999999999 ) ) );
$before_text = count( treda_test_methods( 'sendMessage' ) );
treda_test_run();
$edits = treda_test_methods( 'editMessageCaption' ); $last = end( $edits );
treda_test_expect( (int) $last['params']['message_id'] === 67890 && ! $last['files'] && ! isset( $last['params']['parse_mode'] ) && ! isset( $last['params']['link_preview_options'] ) && strpos( $last['params']['caption'], 'Legacy photo & caption QA' ) === 0, 'Legacy photo caption becomes plain text without replacing or uploading media' );
treda_test_expect( count( treda_test_methods( 'sendMessage' ) ) === $before_text && count( treda_test_methods( 'sendPhoto' ) ) === $before_photos && ! treda_test_methods( 'editMessageMedia' ) && get_post_meta( $legacy, '_treda_publication', true )['message_id'] === 67890, 'Updating legacy media never creates a duplicate or changes its discussion identity' );
$calls = count( $treda_test_calls ); Treda_Queue::post( $legacy ); treda_test_run();
treda_test_expect( count( $treda_test_calls ) === $calls, 'Repeated unchanged legacy caption update is idempotent' );
$long = clone get_post( $legacy ); $long->post_title = str_repeat( '🚀', 250 ); $long->post_excerpt = str_repeat( '🙂 & <strong>text</strong> ', 300 );
$settings['article_link_text'] = str_repeat( '📖', 100 ); update_option( 'treda_settings', $settings );
$caption = Treda_Media::caption( $long );
preg_match_all( '/./us', $caption, $characters ); $units = 0;
foreach ( $characters[0] as $character ) { $units += strlen( $character ) === 4 ? 2 : 1; }
treda_test_expect( $units <= 1024 && substr( $caption, -strlen( get_permalink( $long ) ) ) === get_permalink( $long ) && strpos( $caption, '<strong>' ) === false, 'Emoji-heavy legacy caption fits 1024 UTF-16 units and keeps the entire visible URL' );
$long_url = static function () { return 'https://site.example/' . str_repeat( 'a', 4100 ); };
add_filter( 'post_link', $long_url );
$too_long = Treda_Publisher::text( $long );
treda_test_expect( is_wp_error( $too_long ) && $too_long->get_error_code() === 'treda_link_length', 'An article URL exceeding the Telegram limit is rejected instead of silently truncated' );
remove_filter( 'post_link', $long_url );
$settings['article_link_text'] = ''; update_option( 'treda_settings', $settings );
$uncertain = wp_insert_post( array( 'post_title' => 'Uncertain text preview QA', 'post_status' => 'publish', 'meta_input' => array( '_thumbnail_id' => $attachment ) ) );
$treda_test_next_error = new WP_Error( 'test_timeout', 'Timeout fixture' ); treda_test_run();
treda_test_expect( treda_test_job( 'post:' . $uncertain )->status === 'uncertain', 'A preview send timeout cannot be automatically duplicated' );
remove_filter( 'pre_http_request', 'treda_test_http', 10 );
echo wp_json_encode( array( 'wordpress' => get_bloginfo( 'version' ), 'php' => PHP_VERSION, 'checks' => $treda_test_checks ), JSON_PRETTY_PRINT ) . PHP_EOL;
WP_CLI::success( count( $treda_test_checks ) . ' checks passed, including plain-text previews and legacy media.' );
